"""Private staging, multi-server dispatch and durable recovery metadata in WebView."""
import json,time,re
from desktop_fixture import Peer,Desktop,expect,ROOT
out=ROOT/'artifacts/configurations-ui'
content='events {}\n# private-fixture-config-value\n'+('# configuration data 中文\n'*400)
def audit_clicks(page,app):
    def capture(message):
        if message.text.startswith('CONFIG_UI_CLICK '):
            app.log.write(message.text+'\n');app.log.flush()
    page.on('console',capture)
    page.evaluate("document.addEventListener('click',e=>{const b=e.target.closest('button');if(b)console.log('CONFIG_UI_CLICK '+JSON.stringify({text:b.innerText,x:e.clientX,y:e.clientY,classes:b.className,label:b.getAttribute('aria-label')}))},true)")
with Peer(out/'peer-a') as a, Peer(out/'peer-b') as b:
    profiles=[a.profile('Alpha'),b.profile('Beta'),a.profile('No SFTP')];profiles[-1]['username']='arcnix-nosftp'
    config=a.config(profiles,out)
    host,port=b.data['address'].rsplit(':',1);config['config']['trusted_hosts'].append(dict(host=host,port=int(port),fingerprint=b.data['host_key_rsa_fingerprint']))
    with Desktop(out/f'desktop-{time.time_ns()}',config) as app:
        p=app.page
        audit_clicks(p,app)
        expect(p.locator('.navigation-rail button')).to_have_count(7)
        assert 'rail-servers' in p.locator('.navigation-rail button').first.get_attribute('class')
        p.locator('.rail-configurations').click();expect(p.locator('.module-nav')).to_have_count(0)
        p.get_by_role('button',name='Install Python 3…',exact=True).click();d=p.get_by_role('dialog',name='Run script on servers',exact=True)
        expect(d).to_contain_text("install -- 'python3'");d.get_by_role('button',name='Cancel',exact=True).click()
        p.get_by_role('button',name='Review configuration on servers…',exact=True).click();expect(p.locator('.form-error')).to_contain_text('128 KiB')
        p.get_by_role('textbox',name='Candidate configuration (UTF-8)',exact=True).fill(content)
        p.get_by_role('textbox',name='Application health URL',exact=True).fill('http://user:password@host/')
        p.get_by_role('button',name='Review configuration on servers…',exact=True).click();expect(p.locator('.form-error')).to_contain_text('without credentials')
        p.get_by_role('textbox',name='Application health URL',exact=True).fill('http://127.0.0.1/health')
        app.screenshot('editor.png')
        p.get_by_role('button',name='Review configuration on servers…',exact=True).click();d=p.get_by_role('dialog',name='Run script on servers',exact=True)
        expect(d).to_contain_text('live file is unchanged until execution')
        expect(d.get_by_role('button',name='1',exact=True)).to_have_class(re.compile(r'.*\bchoice active\b.*'))
        d.locator('.target-choice').nth(0).click();d.locator('.target-choice').nth(1).click()
        d.get_by_role('button',name='Check targets',exact=True).click();expect(p.locator('.task-status')).to_have_text(['Ready','Ready'],timeout=20000)
        expect(p.locator('.configuration-diff').first).to_contain_text('private-fixture-config-value')
        assert 'private-fixture-config-value' not in app.config.with_suffix('.tasks.json').read_text()
        app.screenshot('private-diffs.png')
        p.get_by_role('button',name='Execute ready targets',exact=True).click()
        # With a submission limit of one, the next server is dispatched before
        # the first server finishes. A monitor no longer holds a dispatch slot.
        expect(p.locator('.task-status')).to_have_text(['Running','Running'],timeout=20000)
        app.stop();time.sleep(4.5);app.launch();p=app.page;audit_clicks(p,app);p.locator('.rail-configurations').click()
        expect(p.locator('.configuration-phase')).to_have_text(['Result unknown','Result unknown'])
        p.get_by_role('button',name='View task and session diff',exact=True).click()
        assert p.locator('.configuration-diff').evaluate_all('xs=>xs.every(x=>!x.textContent)')
        for index in range(2):
            p.locator('.task-target').nth(index).get_by_role('button',name='Query server result',exact=True).click()
            p.get_by_role('dialog',name='Query server result',exact=True).get_by_role('button',name='Query',exact=True).click()
            expect(p.locator('.task-status').nth(index)).to_have_text('Succeeded',timeout=20000)
        p.locator('.rail-configurations').click();expect(p.locator('.configuration-phase')).to_have_text(['Configuration published and health confirmed']*2)
        app.screenshot('published.png')
        p.locator('.configuration-target').first.get_by_role('button',name='Restore previous recorded version…',exact=True).click()
        d=p.get_by_role('dialog',name='Run script on servers',exact=True);expect(d.locator('.target-choice.active')).to_have_count(1)
        expect(d).to_contain_text('Restore the original server backup')
        d.get_by_role('button',name='Check targets',exact=True).click();expect(p.locator('.task-status')).to_have_text(['Ready'],timeout=20000)
        p.get_by_role('button',name='Execute ready targets',exact=True).click();expect(p.locator('.task-status')).to_have_text(['Succeeded'],timeout=20000)
        p.locator('.rail-configurations').click();expect(p.locator('.configuration-phase').first).to_have_text('Recorded configuration restored and health confirmed')
        p.get_by_role('button',name='Prepare configuration change…',exact=True).click()
        p.get_by_role('button',name='Custom application configuration',exact=True).click()
        p.get_by_role('textbox',name='Candidate configuration (UTF-8)',exact=True).fill(content)
        p.get_by_role('button',name='Review configuration on servers…',exact=True).click();expect(p.locator('.form-error')).to_contain_text('validation, reload and health')
        for label,value in [('Candidate validation command','test -s "$1"'),('Reload command','true'),('Health check command','true')]:p.get_by_role('textbox',name=label,exact=True).fill(value)
        p.get_by_role('textbox',name='Configuration destination',exact=True).fill('/srv/fixture-health-fail.conf')
        p.get_by_role('button',name='Review configuration on servers…',exact=True).click();d=p.get_by_role('dialog',name='Run script on servers',exact=True)
        d.locator('.target-choice').first.click();d.get_by_role('button',name='Check targets',exact=True).click();expect(p.locator('.task-status')).to_have_text(['Ready'],timeout=20000)
        p.get_by_role('button',name='Execute ready targets',exact=True).click();expect(p.locator('.task-status')).to_have_text(['Failed'],timeout=20000)
        p.locator('.rail-configurations').click();expect(p.locator('.configuration-phase').first).to_have_text('Publication failed; previous configuration and service recovered')
        p.get_by_role('button',name='Prepare configuration change…',exact=True).click()
        p.get_by_role('textbox',name='Configuration destination',exact=True).fill('/srv/fixture-submit-fail.conf')
        p.get_by_role('button',name='Review configuration on servers…',exact=True).click();d=p.get_by_role('dialog',name='Run script on servers',exact=True)
        d.locator('.target-choice').nth(0).click();d.locator('.target-choice').nth(1).click();d.get_by_role('button',name='Check targets',exact=True).click();expect(p.locator('.task-status')).to_have_text(['Ready','Ready'],timeout=20000)
        p.get_by_role('button',name='Execute ready targets',exact=True).click();expect(p.locator('.task-status')).to_have_text(['Result unknown','Cancelled'],timeout=20000)
        p.locator('.rail-configurations').click();p.get_by_role('button',name='Prepare configuration change…',exact=True).click()
        p.get_by_role('textbox',name='Configuration destination',exact=True).fill('/srv/application.conf')
        p.get_by_role('button',name='Review configuration on servers…',exact=True).click();d=p.get_by_role('dialog',name='Run script on servers',exact=True)
        d.locator('.target-choice').nth(2).click();d.get_by_role('button',name='Check targets',exact=True).click();expect(p.locator('.task-status')).to_have_text(['Failed'],timeout=20000)
        expect(p.locator('.task-target')).to_contain_text('requires SFTP')
        for iteration in range(3):
            p.locator('.rail-configurations').click();p.get_by_role('button',name='Prepare configuration change…',exact=True).click()
            p.get_by_role('textbox',name='Configuration destination',exact=True).fill('/srv/fixture-health-fail.conf')
            p.get_by_role('button',name='Review configuration on servers…',exact=True).click();d=p.get_by_role('dialog',name='Run script on servers',exact=True)
            d.locator('.target-choice').first.click();d.get_by_role('button',name='Check targets',exact=True).click();expect(p.locator('.task-status')).to_have_text(['Ready'],timeout=20000)
            p.get_by_role('button',name='Execute ready targets',exact=True).click();expect(p.locator('.page-header-title')).to_have_text('Tasks')
            expect(p.locator('.task-status')).to_have_text(['Failed'],timeout=20000)
            p.locator('.rail-configurations').click();expect(p.locator('.configuration-phase').first).to_have_text('Publication failed; previous configuration and service recovered')
        app.settings('General');p.get_by_role('button',name='简体中文',exact=True).click();expect(p.locator('.page-header-title')).to_have_text('常规')
        p.locator('.rail-configurations').click();expect(p.locator('.page-header-title')).to_have_text('配置发布')
        p.set_viewport_size(dict(width=900,height=700));assert p.evaluate('document.documentElement.scrollWidth <= innerWidth');app.screenshot('configurations-chinese.png')
        saved=app.config.read_text()+app.config.with_suffix('.tasks.json').read_text()
        assert 'private-fixture-config-value' not in saved and 'configuration data' not in saved
        history=json.loads(app.config.with_suffix('.tasks.json').read_text());assert len(history)==8
        assert all(t['configuration'] is not None for t in history)
        app.stop();app.launch();p=app.page;p.locator('.rail-configurations').click();expect(p.locator('.configuration-run')).to_have_count(8)
(out/'results.json').write_text(json.dumps(dict(passed=True,checks=['global entry after Servers','no active server required','Python installer entry','bounded content validation','credential URL rejection','private staged upload larger than stdin limit','per-server diff','diff excluded from history','one-slot dispatch does not wait for runtime completion','submitted jobs survive closing client','restart queries without resubmission','session-only diff disappears after restart','published health confirmation','restore preselects original server','explicit server-backup restore','custom validation required','failed publication shows recovered state','submission failure stops pending targets','SFTP capability failure','Chinese narrow layout and metadata persistence','repeated execution routing with pointer audit']),indent=2))
print('21 configuration UI checks passed, including three repeated publication routes')
